"""Recompute exp-001 conditional metrics with the correct greedy_f1 > 0 filter."""
import json
import sys
import numpy as np
from collections import Counter
from scipy.stats import spearmanr, kendalltau

sys.path.insert(0, "/root/autodl-tmp/struct_self_consist_ie/code")
from consistency import compute_all_consistency_scores
from evaluation import per_instance_f1

SAMPLES_PATH = "/root/autodl-tmp/struct_self_consist_ie/output/exp001_n16_seed42/samples.jsonl"
OUT_PATH = "/root/autodl-tmp/struct_self_consist_ie/output/exp001_n16_seed42/corrected_conditional_metrics.json"

def load_jsonl(path):
    instances = []
    with open(path) as f:
        for line in f:
            if line.strip():
                instances.append(json.loads(line))
    return instances

def auroc_simple(scores, labels):
    scores = np.array(scores, dtype=float)
    labels = np.array(labels, dtype=int)
    if len(set(labels)) < 2:
        return float('nan')
    pos = scores[labels == 1]
    neg = scores[labels == 0]
    if len(pos) == 0 or len(neg) == 0:
        return float('nan')
    count = 0.0
    for p in pos:
        count += np.sum(p > neg) + 0.5 * np.sum(p == neg)
    return count / (len(pos) * len(neg))

def entity_set_key(sample):
    return frozenset((e["text"], e["type"]) for e in sample.get("entities", []))

def relation_set_key(sample):
    return frozenset((r["head"], r["tail"], r["type"]) for r in sample.get("relations", []))

def exact_match_rate(samples, subtask):
    if not samples:
        return 0.0
    key_fn = entity_set_key if subtask == "ner" else relation_set_key
    keys = [key_fn(s) for s in samples]
    counter = Counter(keys)
    return counter.most_common(1)[0][1] / len(samples)

def voting_confidence(samples, subtask):
    N = len(samples)
    if N == 0:
        return 0.0
    counter = Counter()
    if subtask == "ner":
        for s in samples:
            for e in s.get("entities", []):
                counter[(e["text"], e["type"])] += 1
    else:
        for s in samples:
            for r in s.get("relations", []):
                counter[(r["head"], r["tail"], r["type"])] += 1
    if not counter:
        return 0.0
    return float(np.mean([c / N for c in counter.values()]))

print("Loading samples...")
instances = load_jsonl(SAMPLES_PATH)
print(f"Loaded {len(instances)} instances, N_samples={len(instances[0]['samples'])}")

has_logprobs = "logprobs" in instances[0]
report = {"n_instances": len(instances), "n_samples": len(instances[0]["samples"]), "filter_definition": "greedy_f1 > 0"}

for subtask in ["ner", "re"]:
    print(f"\n{'='*60}")
    print(f"Subtask: {subtask.upper()}")

    # Consistency scores
    consistency = compute_all_consistency_scores(instances, subtask=subtask)
    sj = consistency["soft_jaccard"]
    fk = consistency["fleiss_kappa"]

    # Per-instance greedy F1
    greedy_f1s = [per_instance_f1(inst["greedy"], inst["gold"], subtask) for inst in instances]

    # Exact match rate, voting confidence
    em_rates = [exact_match_rate(inst["samples"], subtask) for inst in instances]
    v_confs = [voting_confidence(inst["samples"], subtask) for inst in instances]

    # Logprobs
    logprobs = []
    for inst in instances:
        if "logprobs" in inst:
            logprobs.append(float(np.mean(inst["logprobs"])))
        else:
            logprobs.append(None)

    # Filter: gold non-empty
    field = "entities" if subtask == "ner" else "relations"
    valid = [i for i, inst in enumerate(instances) if inst["gold"].get(field)]
    n_gold_empty = len(instances) - len(valid)

    f1_v = [greedy_f1s[i] for i in valid]
    median_full = float(np.median(f1_v))
    labels_full = [1 if f > median_full else 0 for f in f1_v]

    # Conditional: greedy_f1 > 0 (STANDARD DEFINITION)
    cond = [i for i in valid if greedy_f1s[i] > 0]
    f1_c = [greedy_f1s[i] for i in cond]
    median_cond = float(np.median(f1_c)) if f1_c else 0.0
    labels_cond = [1 if f > median_cond else 0 for f in f1_c]

    n_full = len(valid)
    n_cond = len(cond)
    print(f"  n_total={len(instances)}, n_valid={n_full}, n_cond={n_cond}, n_gold_empty={n_gold_empty}")

    signals = {
        "soft_jaccard": sj,
        "fleiss_kappa": fk,
        "exact_match_rate": em_rates,
        "voting_confidence": v_confs,
    }
    if has_logprobs:
        signals["logprob"] = logprobs

    corr = {}
    for name, scores in signals.items():
        sc_v = [scores[i] for i in valid]
        sc_c = [scores[i] for i in cond]

        if any(s is None for s in sc_v):
            sc_v_clean = [(s, f) for s, f in zip(sc_v, f1_v) if s is not None]
            sc_c_clean = [(s, f) for s, f in zip(sc_c, f1_c) if s is not None]
            if len(sc_v_clean) < 3:
                corr[name] = {"rho": None, "tau": None, "auroc": None,
                              "n_full": n_full, "rho_cond": None, "tau_cond": None, "auroc_cond": None, "n_cond": n_cond}
                continue
            sv, fv = zip(*sc_v_clean)
            rho = float(spearmanr(sv, fv).statistic)
            tau = float(kendalltau(sv, fv).statistic)
            auc = auroc_simple(list(sv), [1 if f > median_full else 0 for f in fv])
            if len(sc_c_clean) >= 3:
                sc, fc = zip(*sc_c_clean)
                rho_c = float(spearmanr(sc, fc).statistic)
                tau_c = float(kendalltau(sc, fc).statistic)
                auc_c = auroc_simple(list(sc), [1 if f > median_cond else 0 for f in fc])
            else:
                rho_c, tau_c, auc_c = 0.0, 0.0, 0.5
        else:
            rho = float(spearmanr(sc_v, f1_v).statistic)
            tau = float(kendalltau(sc_v, f1_v).statistic)
            auc = auroc_simple(sc_v, labels_full)
            if len(sc_c) >= 3:
                rho_c = float(spearmanr(sc_c, f1_c).statistic)
                tau_c = float(kendalltau(sc_c, f1_c).statistic)
                auc_c = auroc_simple(sc_c, labels_cond)
            else:
                rho_c, tau_c, auc_c = 0.0, 0.0, 0.5

        corr[name] = {
            "rho": rho, "tau": tau, "auroc": float(auc) if not np.isnan(auc) else None,
            "n_full": n_full,
            "rho_cond": rho_c, "tau_cond": tau_c, "auroc_cond": float(auc_c) if not np.isnan(auc_c) else None,
            "n_cond": n_cond,
        }
        print(f"  {name:<20} full ρ={rho:+.4f}  cond ρ={rho_c:+.4f}")

    report[subtask] = {
        "correlations": corr,
        "n_valid": n_full,
        "n_cond": n_cond,
        "n_gold_empty": n_gold_empty,
        "greedy_f1_mean": float(np.mean(greedy_f1s)),
    }

with open(OUT_PATH, "w") as f:
    json.dump(report, f, indent=2, ensure_ascii=False)
print(f"\nCorrected metrics saved to {OUT_PATH}")
PYEOF
